/**
 * Backfills the title and ending pages on books created before the finished
 * structure existed (or regenerated by an older build that dropped them).
 *
 * A finished book is: [front cover] · title · story×N · ending · [back cover].
 * Books made before that only have the story pages, so they open straight onto
 * page 1 of the story with no title page and no "The End". This adds the two
 * missing structural pages to every book that lacks them.
 *
 * Safe and idempotent: it uses the same `prepareForPrint` the in-app "Add the
 * missing title & ending pages" button uses, which only adds a page type the
 * book does not already have. Re-running it is a no-op. It never touches story
 * pages, covers, or any book that is already complete.
 *
 * Run once against a real database:  node scripts/backfill-structural-pages.js
 */
import { connectDatabase, disconnectDatabase } from '../src/config/db.js';
import { Book } from '../src/models/index.js';
import { prepareForPrint } from '../src/modules/pages/pages.service.js';
import { logger } from '../src/config/logger.js';

async function main() {
  await connectDatabase();

  const books = await Book.find({}).select('_id title ownerId');
  logger.info({ total: books.length }, 'Books to check');

  let titles = 0;
  let endings = 0;
  for (const book of books) {
    const { addedTitle, addedEnding } = await prepareForPrint({ book });
    if (addedTitle) titles += 1;
    if (addedEnding) endings += 1;
    if (addedTitle || addedEnding) {
      logger.info(
        { bookId: String(book._id), addedTitle, addedEnding },
        `Backfilled ${book.title}`,
      );
    }
  }

  logger.info({ titles, endings }, 'Backfill complete');
  await disconnectDatabase();
}

main().catch(async (err) => {
  logger.error({ err }, 'Structural-page backfill failed');
  await disconnectDatabase().catch(() => {});
  process.exitCode = 1;
});
